using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;

var build = BinaryLog.ReadBuild("/tmp/sv-344d5e5445fd40c4a3920d78aaccf8af/build.binlog");
Console.WriteLine($"Build succeeded: {build.Succeeded}");
Console.WriteLine();

// Find all errors
var errors = build.FindChildrenRecursive<Error>();
Console.WriteLine($"=== ERRORS ({errors.Count}) ===");
foreach (var error in errors)
{
    Console.WriteLine($"[{error.Code}] {error.File}({error.LineNumber},{error.ColumnNumber}): {error.Text}");
    // Find parent project
    var parent = error.Parent;
    while (parent != null && parent is not Project)
        parent = parent.Parent;
    if (parent is Project proj)
        Console.WriteLine($"  In project: {proj.Name}");
    Console.WriteLine();
}

// Find all warnings
var warnings = build.FindChildrenRecursive<Warning>();
Console.WriteLine($"\n=== WARNINGS ({warnings.Count}) ===");
foreach (var w in warnings)
{
    Console.WriteLine($"[{w.Code}] {w.File}({w.LineNumber},{w.ColumnNumber}): {w.Text}");
}
EOF

