using Microsoft.Build.Logging.StructuredLogger;
using System;

var build = BinaryLog.ReadBuild("/tmp/sv-344d5e5445fd40c4a3920d78aaccf8af/build.binlog");

// Find Csc task invocations to see compiler command lines
var tasks = build.FindChildrenRecursive<Task>();
foreach (var task in tasks)
{
    if (task.Name == "Csc")
    {
        Console.WriteLine($"\n=== Csc in {task.Parent?.Parent} ===");
        // Look at command line args
        foreach (var child in task.Children)
        {
            if (child is Message msg && msg.Text != null && msg.Text.Contains("/tmp/sv-"))
            {
                Console.WriteLine(msg.Text.Substring(0, Math.Min(msg.Text.Length, 500)));
            }
            if (child is Error err)
            {
                Console.WriteLine($"  ERROR [{err.Code}] {err.File}:{err.LineNumber} - {err.Text}");
            }
        }
    }
}

// Also check which projects failed
Console.WriteLine("\n=== PROJECT BUILD RESULTS ===");
var projects = build.FindChildrenRecursive<Project>();
foreach (var p in projects)
{
    Console.WriteLine($"{p.Name} - Children: {p.Children.Count}");
    foreach (var child in p.Children)
    {
        if (child is Target t && !t.IsLowRelevance)
        {
            foreach (var tc in t.Children)
            {
                if (tc is Error e)
                    Console.WriteLine($"  FAILED target {t.Name}: [{e.Code}] {e.Text}");
            }
        }
    }
}
EOF
